### Monto total por partido


::: {.cell}

```{.r .cell-code}
# Usa la paleta institucional de partidos definida en utils.R
contratos_montos |>
  filter(costo > 0) |>
  group_by(partido) |>
  summarise(
    monto_total = sum(costo, na.rm = TRUE),
    .groups     = "drop"
  ) |>
  mutate(partido = fct_reorder(partido, monto_total)) |>
  ggplot(aes(x = monto_total, y = partido, fill = partido)) +
  geom_col(alpha = 0.92, show.legend = FALSE) +
  scale_fill_manual(values = paleta_partidos) +
  scale_x_continuous(labels = label_dollar(scale = 1e-6, big.mark = ","),
                     name = "Monto total (millones de MXN)") +
  labs(
    title    = "Monto total de contratos por partido político",
    subtitle = "Solo contratos con costo > 0 · contratos_montos.csv",
    y        = NULL,
    caption  = "Fuente: MCCI"
  ) +
  theme_minimal(base_size = 13) +
  theme(
    plot.title    = element_text(color = "#0d1b2a", face = "bold"),
    plot.subtitle = element_text(color = "#64748b"),
    axis.text     = element_text(color = "#1e293b"),
    panel.grid.major.y = element_blank()
  )
